depth=pos.w;motion=-texelFetch(velocity,p,0).xy*vec2(textureSize(velocity,0));
vec3 n=texelFetch(normals,p,0).xyz;bool valid=pos.w<1 && dot(n,n)>.01;
diffuse=vec4(valid?texelFetch(albedo,p,0).rgb:vec3(0),1);
